/**
 * The "Asset Handover & Custody Notice" poster, embedded here as base64 so it ships inside the
 * serverless function bundle without depending on Next.js's static-file tracing (which doesn't
 * reliably pick up a binary file read from disk at runtime on Vercel). Attached to every receipt
 * email alongside the receipt PDF -- it's the document the acknowledgment text refers to
 * ("...liable for the penalty amounts stated in the Asset Handover and Custody Notice").
 *
 * To swap in an updated poster: export the new one as PDF, compress/flatten it to keep email size
 * sane (e.g. `pdftoppm -r 200 -png new.pdf page && ` convert page-1.png to a ~80%-quality JPEG and
 * wrap it back into a single-page PDF with img2pdf), then `base64 -w0 new-poster.pdf` and paste the
 * result in below.
 */
const ASSET_HANDOVER_POSTER_BASE64 =
  "";

export function assetHandoverPosterPdf(): Buffer {
  return Buffer.from(ASSET_HANDOVER_POSTER_BASE64, "base64");
}
